package ru.neverland.townyspecialization.production;

import java.io.*;
import java.nio.file.*;
import java.sql.*;
import java.util.*;
import java.util.concurrent.*;
import org.bukkit.configuration.file.YamlConfiguration;
import ru.neverland.core.SuiteState;

/** Single bounded SQLite writer. Contracts consumes physical materials; this ledger accounts their unique output. */
public final class ProductionRepository {
    public record Batch(UUID id,UUID town,String product,String profile,String title,int amount,String state,Map<String,Long> materials,String actor,long created){
        public Batch{Objects.requireNonNull(id);Objects.requireNonNull(town);ProductionCatalog.identifier(product);text(title,100);text(actor,64);if(!ru.neverland.integration.SpecializationRules.PROJECTS.containsValue(profile)||created<0)throw new IllegalArgumentException("Неверная сохранённая партия");materials=Map.copyOf(materials);if(materials.isEmpty()||materials.size()>16||materials.entrySet().stream().anyMatch(e->!e.getKey().matches("[A-Z0-9_]{1,64}")||e.getValue()<1||e.getValue()>6_400_000))throw new IllegalArgumentException("Неверная сохранённая смета");if(amount<1||amount>64||!Set.of("PLANNING","OPEN","FINISHING","CANCELLING","ISSUED","CANCELLED").contains(state))throw new IllegalArgumentException("Неверная партия");}
        public String contract(){return "batch_"+id.toString().replace("-","");}
        public String unlock(){return "joint_batch_"+id.toString().replace("-","");}
        public String label(){return "Партия: "+title+" × "+amount;}
    }
    public record Stock(String product,String profile,String title,long available,long reserved,long produced){public Stock{if(available<0||reserved<0||produced<Math.addExact(available,reserved))throw new IllegalArgumentException("Повреждён учёт производственных партий");}}
    public record Joint(UUID id,UUID owner,String title,String result,int minimumCities,Map<String,Long> goods,Map<String,String> profiles,String state,long created){public Joint{Objects.requireNonNull(id);Objects.requireNonNull(owner);text(title,100);text(result,200);goods=Map.copyOf(goods);profiles=Map.copyOf(profiles);if(minimumCities<2||minimumCities>7||created<0||!Set.of("OPEN","COMPLETED","CANCELLED").contains(state)||goods.size()<2||goods.size()>7||!goods.keySet().equals(profiles.keySet())||goods.values().stream().anyMatch(n->n<1||n>64)||!ru.neverland.integration.SpecializationRules.PROJECTS.values().containsAll(profiles.values())||new HashSet<>(profiles.values()).size()<minimumCities)throw new IllegalArgumentException("Неверный сохранённый совместный проект");goods.keySet().forEach(ProductionCatalog::identifier);}}
    public record JointView(Joint project,Map<String,Long> supplied,Map<UUID,String> members,List<Map<String,Object>> contributions){public JointView{supplied=Map.copyOf(supplied);members=Map.copyOf(members);contributions=List.copyOf(contributions);}public boolean funded(){return members.size()>=project.minimumCities()&&new HashSet<>(members.values()).size()>=project.minimumCities()&&project.goods().entrySet().stream().allMatch(e->supplied.getOrDefault(e.getKey(),0L)>=e.getValue());}}
    @FunctionalInterface private interface Sql<T>{T run()throws Exception;}
    private final Path file;private final ThreadPoolExecutor worker;private final CompletableFuture<Void> ready,closed=new CompletableFuture<>();private Connection db;private volatile boolean closing,fault,initialized;
    public ProductionRepository(Path file){this.file=file.toAbsolutePath();worker=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(128),r->{var t=new Thread(r,"NeverLand-profile-products");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy()){@Override protected void terminated(){Throwable failure=null;try{if(db!=null&&initialized)try(var s=db.createStatement()){s.execute("PRAGMA busy_timeout=1000");try(var r=s.executeQuery("PRAGMA wal_checkpoint(TRUNCATE)")){if(!r.next()||r.getInt(1)!=0||r.getInt(2)!=0||r.getInt(3)!=0)throw new IOException("Производственный каталог не подтвердил остановку WAL");}}}catch(Throwable e){failure=e;}finally{try{if(db!=null)db.close();}catch(Throwable e){if(failure==null)failure=e;else failure.addSuppressed(e);}}if(failure==null)closed.complete(null);else closed.completeExceptionally(failure);}};ready=submit(()->{open();initialized=true;return null;});}
    public CompletionStage<Void> ready(){return ready;}public boolean available(){return ready.isDone()&&!ready.isCompletedExceptionally()&&!fault&&!closing;}
    public synchronized CompletionStage<Void> closeAsync(){closing=true;worker.shutdown();return closed;}
    private <T>CompletableFuture<T> submit(Sql<T> job){var f=new CompletableFuture<T>();if(closing){f.completeExceptionally(new IOException("Производственный каталог останавливается"));return f;}try{worker.execute(()->{try{if(SuiteState.held())throw new IllegalStateException("SQL под общей блокировкой");if(fault)throw new IOException("Производственный каталог требует проверки");f.complete(job.run());}catch(Throwable e){if(e instanceof SQLException||e instanceof IOException)fault=true;f.completeExceptionally(e);}});}catch(RejectedExecutionException full){f.completeExceptionally(new IllegalStateException("Каталог занят; повторите позже"));}return f;}
    private void open()throws Exception{Files.createDirectories(file.getParent());Class.forName("org.sqlite.JDBC");db=DriverManager.getConnection("jdbc:sqlite:"+file);try(var s=db.createStatement()){
        s.execute("PRAGMA foreign_keys=ON");s.execute("PRAGMA busy_timeout=1000");try(var r=s.executeQuery("PRAGMA journal_mode=WAL")){if(!r.next()||!r.getString(1).equalsIgnoreCase("wal"))throw new IOException("Нужна поддержка SQLite WAL");}s.execute("PRAGMA synchronous=FULL");try(var r=s.executeQuery("PRAGMA user_version")){if(!r.next()||r.getInt(1)>1)throw new IOException("Неизвестная версия производственного каталога");}try(var r=s.executeQuery("PRAGMA quick_check")){if(!r.next()||!r.getString(1).equals("ok"))throw new IOException("Повреждён производственный каталог");}
        s.execute("CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,profile TEXT NOT NULL,title TEXT NOT NULL)");
        s.execute("CREATE TABLE IF NOT EXISTS batches(id TEXT PRIMARY KEY,town TEXT NOT NULL,product TEXT NOT NULL REFERENCES products(id),profile TEXT NOT NULL,title TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),state TEXT NOT NULL,materials TEXT NOT NULL,actor TEXT NOT NULL,created INTEGER NOT NULL)");
        s.execute("CREATE TABLE IF NOT EXISTS stock(town TEXT NOT NULL,product TEXT NOT NULL REFERENCES products(id),available INTEGER NOT NULL CHECK(available>=0),reserved INTEGER NOT NULL CHECK(reserved>=0),produced INTEGER NOT NULL CHECK(produced>=available+reserved),PRIMARY KEY(town,product))");
        s.execute("CREATE TABLE IF NOT EXISTS joint_projects(id TEXT PRIMARY KEY,owner TEXT NOT NULL,title TEXT NOT NULL,result TEXT NOT NULL,minimum_cities INTEGER NOT NULL,goods TEXT NOT NULL,profiles TEXT NOT NULL,state TEXT NOT NULL,created INTEGER NOT NULL)");
        s.execute("CREATE TABLE IF NOT EXISTS joint_members(project TEXT NOT NULL REFERENCES joint_projects(id),town TEXT NOT NULL,profile TEXT NOT NULL,PRIMARY KEY(project,town))");
        s.execute("CREATE TABLE IF NOT EXISTS joint_contributions(receipt TEXT PRIMARY KEY,project TEXT NOT NULL REFERENCES joint_projects(id),town TEXT NOT NULL,product TEXT NOT NULL REFERENCES products(id),amount INTEGER NOT NULL CHECK(amount>0),actor TEXT NOT NULL,at INTEGER NOT NULL)");
        s.execute("CREATE TABLE IF NOT EXISTS history(id TEXT PRIMARY KEY,kind TEXT NOT NULL,operation TEXT NOT NULL,town TEXT NOT NULL,actor TEXT NOT NULL,reason TEXT NOT NULL,at INTEGER NOT NULL)");
        s.execute("CREATE TABLE IF NOT EXISTS audit_ack(id TEXT PRIMARY KEY REFERENCES history(id))");
        s.execute("CREATE INDEX IF NOT EXISTS batches_city ON batches(town,state)");s.execute("CREATE INDEX IF NOT EXISTS joint_owner ON joint_projects(owner,state)");s.execute("CREATE INDEX IF NOT EXISTS contributions_project ON joint_contributions(project,town)");s.execute("CREATE INDEX IF NOT EXISTS history_town ON history(town,at)");s.execute("PRAGMA user_version=1");
    }}
    private <T>T transaction(Sql<T> job)throws Exception{db.setAutoCommit(false);try{T value=job.run();db.commit();return value;}catch(Throwable e){try{db.rollback();}catch(SQLException rollback){e.addSuppressed(rollback);}throw e;}finally{db.setAutoCommit(true);}}
    private long scalar(String sql,Object...args)throws SQLException{try(var s=db.prepareStatement(sql)){for(int i=0;i<args.length;i++)s.setObject(i+1,args[i]);try(var r=s.executeQuery()){return r.next()?r.getLong(1):0;}}}
    private void exec(String sql,Object...args)throws SQLException{try(var s=db.prepareStatement(sql)){for(int i=0;i<args.length;i++)s.setObject(i+1,args[i]);s.executeUpdate();}}
    private static String encode(Map<?,?> values){var y=new YamlConfiguration();values.forEach((k,v)->y.set(k.toString(),v));return y.saveToString();}
    private static Map<String,Long> quantities(String text)throws Exception{var y=new YamlConfiguration();y.loadFromString(text);var out=new TreeMap<String,Long>();for(String k:y.getKeys(false)){long n=new java.math.BigDecimal(String.valueOf(y.get(k))).longValueExact();if(n<1)throw new IOException("Некорректное количество в каталоге");out.put(k,n);}return Map.copyOf(out);}
    private static Map<String,String> profiles(String text)throws Exception{var y=new YamlConfiguration();y.loadFromString(text);var out=new TreeMap<String,String>();for(String k:y.getKeys(false)){if(!(y.get(k) instanceof String s))throw new IOException("Некорректный профиль в каталоге");out.put(k,s);}return Map.copyOf(out);}
    private void product(ProductionCatalog.Product p)throws Exception{try(var s=db.prepareStatement("SELECT profile FROM products WHERE id=?")){s.setString(1,p.id());try(var r=s.executeQuery()){if(r.next()){if(!r.getString(1).equals(p.profile()))throw new IllegalArgumentException("Товар уже закреплён за другим направлением");return;}}}exec("INSERT INTO products VALUES(?,?,?)",p.id(),p.profile(),p.title());}
    private Batch readBatch(UUID id)throws Exception{try(var s=db.prepareStatement("SELECT * FROM batches WHERE id=?")){s.setString(1,id.toString());try(var r=s.executeQuery()){return r.next()?new Batch(id,UUID.fromString(r.getString("town")),r.getString("product"),r.getString("profile"),r.getString("title"),r.getInt("amount"),r.getString("state"),quantities(r.getString("materials")),r.getString("actor"),r.getLong("created")):null;}}}
    public CompletionStage<Batch> batch(UUID id){return submit(()->readBatch(id));}
    public CompletionStage<List<Batch>> batches(UUID town,int page){return submit(()->{page(page);var rows=new ArrayList<Batch>();try(var s=db.prepareStatement("SELECT id FROM batches WHERE town=? ORDER BY created DESC,id LIMIT 20 OFFSET ?")){s.setString(1,town.toString());s.setLong(2,(page-1L)*20);try(var r=s.executeQuery()){while(r.next())rows.add(readBatch(UUID.fromString(r.getString(1))));}}return List.copyOf(rows);});}
    private static void page(int page){if(page<1||page>10000)throw new IllegalArgumentException("Неверная страница");}
    private static void text(String value,int max){if(value==null||value.isBlank()||value.length()>max)throw new IllegalArgumentException("Неверное основание или имя");}
    private long capacity(UUID town)throws SQLException{String where=town==null?"":" WHERE town=?";Object[] args=town==null?new Object[0]:new Object[]{town.toString()};return Math.addExact(scalar("SELECT COALESCE(SUM(available+reserved),0) FROM stock"+where,args),scalar("SELECT COALESCE(SUM(amount),0) FROM batches WHERE state NOT IN ('ISSUED','CANCELLED')"+(town==null?"":" AND town=?"),args));}
    public CompletionStage<Batch> createBatch(UUID id,UUID town,ProductionCatalog.Product product,int amount,String actor,ProductionCatalog.Limits limits){return submit(()->transaction(()->{
        text(actor,64);if(amount<1||amount>limits.batchSize())throw new IllegalArgumentException("Количество партий превышает предел");var old=readBatch(id);if(old!=null){if(!old.town().equals(town)||!old.product().equals(product.id())||!old.profile().equals(product.profile())||old.amount()!=amount||!old.materials().equals(product.costs(amount)))throw new IllegalArgumentException("ID уже занят другой партией");return old;}
        if(scalar("SELECT COUNT(*) FROM batches WHERE town=? AND state NOT IN ('ISSUED','CANCELLED')",town.toString())>=limits.activeBatchesCity()||scalar("SELECT COUNT(*) FROM batches WHERE state NOT IN ('ISSUED','CANCELLED')")>=limits.activeBatchesServer())throw new IllegalArgumentException("Достигнут предел незавершённых партий");
        if(Math.addExact(capacity(town),amount)>limits.goodsCity()||Math.addExact(capacity(null),amount)>limits.goodsServer())throw new IllegalArgumentException("Городской каталог заполнен; используйте сохранённые партии в совместных проектах");
        product(product);exec("INSERT INTO batches VALUES(?,?,?,?,?,?,'PLANNING',?,?,?)",id.toString(),town.toString(),product.id(),product.profile(),product.title(),amount,encode(product.costs(amount)),actor,System.currentTimeMillis());log("batch-plan",id.toString(),town,actor,"Смета сохранена; материалы ещё не списаны");return readBatch(id);
    }));}
    public CompletionStage<Batch> mark(UUID id,boolean cancel,String actor){return submit(()->transaction(()->{var b=Objects.requireNonNull(readBatch(id),"Партия не найдена");if(Set.of("ISSUED","CANCELLED").contains(b.state()))return b;String goal=cancel?"CANCELLING":"FINISHING";if((b.state().equals("FINISHING")&&cancel)||(b.state().equals("CANCELLING")&&!cancel))throw new IllegalArgumentException("Сначала сверьте предыдущую операцию партии");exec("UPDATE batches SET state=? WHERE id=?",goal,id.toString());log(goal,id.toString(),b.town(),actor,"Ожидаем подтверждение сметы материалов");return readBatch(id);}));}
    public static String validateSource(Batch b,Map<String,Object> source){
        if(source.isEmpty())return "MISSING";Object raw=source.get("minimumCredit");long min=-1;try{if(raw instanceof Number)min=new java.math.BigDecimal(raw.toString()).longValueExact();}catch(ArithmeticException ignored){}
        if(!b.contract().equals(source.get("id"))||!b.label().equals(source.get("title"))||!"CITY".equals(source.get("scope"))||!b.town().toString().equals(source.get("ownerTown"))||!b.unlock().equals(source.get("unlock"))||min!=1||!b.materials().equals(source.get("needs")))throw new IllegalArgumentException("Квитанция материалов относится к другой смете; партия не выдана");
        String state=String.valueOf(source.get("state"));if(!Set.of("OPEN","COMPLETED","CANCELLED").contains(state))throw new IllegalArgumentException("Неизвестный результат сметы");if(state.equals("COMPLETED")&&(!Boolean.TRUE.equals(source.get("funded"))||!b.materials().equals(source.get("credited"))))throw new IllegalArgumentException("Не подтверждён точный расход материалов партии");return state;
    }
    /** A unique batch ID is credited atomically with ISSUED; a repeated external receipt cannot mint it again. */
    public CompletionStage<Batch> acknowledge(UUID id,Map<String,Object> proof,String actor){return submit(()->transaction(()->{
        var b=Objects.requireNonNull(readBatch(id),"Партия не найдена");String state=validateSource(b,proof);if(state.equals("MISSING"))return b;
        if(state.equals("COMPLETED")){if(b.state().equals("ISSUED"))return b;if(b.state().equals("CANCELLED"))throw new IllegalArgumentException("Отменённая партия получила противоречивую квитанцию");
            Math.addExact(scalar("SELECT produced FROM stock WHERE town=? AND product=?",b.town().toString(),b.product()),b.amount());
            Math.addExact(scalar("SELECT available FROM stock WHERE town=? AND product=?",b.town().toString(),b.product()),b.amount());
            exec("INSERT INTO stock(town,product,available,reserved,produced) VALUES(?,?,?,0,?) ON CONFLICT(town,product) DO UPDATE SET available=available+excluded.available,produced=produced+excluded.produced",b.town().toString(),b.product(),b.amount(),b.amount());exec("UPDATE batches SET state='ISSUED' WHERE id=?",id.toString());log("batch-issued",id.toString(),b.town(),actor,"Материалы использованы по смете "+b.contract()+"; учтено партий: "+b.amount());
        }else if(state.equals("CANCELLED")){if(b.state().equals("ISSUED"))throw new IllegalArgumentException("Выданная партия получила противоречивую отмену");exec("UPDATE batches SET state='CANCELLED' WHERE id=?",id.toString());log("batch-cancelled",id.toString(),b.town(),actor,"Резерв материалов возвращён серверному складу");}
        else if(b.state().equals("PLANNING"))exec("UPDATE batches SET state='OPEN' WHERE id=?",id.toString());return readBatch(id);
    }));}
    public CompletionStage<List<Stock>> stock(UUID town){return stock(town,1);}
    public CompletionStage<List<Stock>> stock(UUID town,int page){return submit(()->{page(page);var rows=new ArrayList<Stock>();try(var s=db.prepareStatement("SELECT s.product,p.profile,p.title,s.available,s.reserved,s.produced FROM stock s JOIN products p ON p.id=s.product WHERE town=? ORDER BY (s.available+s.reserved>0) DESC,product LIMIT 20 OFFSET ?")){s.setString(1,town.toString());s.setLong(2,(page-1L)*20);try(var r=s.executeQuery()){while(r.next())rows.add(new Stock(r.getString(1),r.getString(2),r.getString(3),r.getLong(4),r.getLong(5),r.getLong(6)));}}return List.copyOf(rows);});}
    private Joint readJoint(UUID id)throws Exception{try(var s=db.prepareStatement("SELECT * FROM joint_projects WHERE id=?")){s.setString(1,id.toString());try(var r=s.executeQuery()){return r.next()?new Joint(id,UUID.fromString(r.getString("owner")),r.getString("title"),r.getString("result"),r.getInt("minimum_cities"),quantities(r.getString("goods")),profiles(r.getString("profiles")),r.getString("state"),r.getLong("created")):null;}}}
    private JointView readView(UUID id)throws Exception{var p=readJoint(id);if(p==null)throw new IllegalArgumentException("Совместный проект не найден");var supplied=new TreeMap<String,Long>();var members=new LinkedHashMap<UUID,String>();var contributions=new ArrayList<Map<String,Object>>();try(var s=db.prepareStatement("SELECT town,profile FROM joint_members WHERE project=? ORDER BY town")){s.setString(1,id.toString());try(var r=s.executeQuery()){while(r.next())members.put(UUID.fromString(r.getString(1)),r.getString(2));}}
        try(var s=db.prepareStatement("SELECT receipt,town,product,amount,actor,at FROM joint_contributions WHERE project=? ORDER BY at,receipt")){s.setString(1,id.toString());try(var r=s.executeQuery()){while(r.next()){String product=r.getString(3);long amount=r.getLong(4);if(amount<1||amount>64||!p.goods().containsKey(product)||!Objects.equals(p.profiles().get(product),members.get(UUID.fromString(r.getString(2)))))throw new IOException("Повреждена квитанция совместного проекта");supplied.merge(product,amount,Math::addExact);if(supplied.get(product)>p.goods().get(product))throw new IOException("Резерв превышает смету");contributions.add(Map.of("receipt",r.getString(1),"town",r.getString(2),"product",r.getString(3),"amount",r.getLong(4),"actor",r.getString(5),"at",r.getLong(6)));}}}
        return new JointView(p,supplied,members,contributions);
    }
    public CompletionStage<JointView> joint(UUID id){return submit(()->readView(id));}
    public CompletionStage<List<Joint>> projects(int page){return submit(()->{page(page);var out=new ArrayList<Joint>();try(var s=db.prepareStatement("SELECT id FROM joint_projects ORDER BY created DESC,id LIMIT 20 OFFSET ?")){s.setLong(1,(page-1L)*20);try(var r=s.executeQuery()){while(r.next())out.add(readJoint(UUID.fromString(r.getString(1))));}}return List.copyOf(out);});}
    public CompletionStage<JointView> createProject(UUID id,UUID owner,ProductionCatalog.Joint template,Map<String,ProductionCatalog.Product> products,String actor,ProductionCatalog.Limits limits){return submit(()->transaction(()->{
        var profiles=new TreeMap<String,String>();for(String key:template.goods().keySet()){var p=Objects.requireNonNull(products.get(key),"Неизвестный товар");product(p);profiles.put(key,p.profile());}
        var old=readJoint(id);if(old!=null){if(!old.owner().equals(owner)||!old.title().equals(template.title())||!old.result().equals(template.result())||!old.goods().equals(template.goods())||!old.profiles().equals(profiles)||old.minimumCities()!=template.minimumCities())throw new IllegalArgumentException("ID занят другим совместным проектом");return readView(id);}
        if(scalar("SELECT COUNT(*) FROM joint_projects WHERE owner=? AND state='OPEN'",owner.toString())>=limits.activeProjectsCity()||scalar("SELECT COUNT(*) FROM joint_projects WHERE state='OPEN'")>=limits.activeProjectsServer())throw new IllegalArgumentException("Достигнут предел открытых совместных проектов");
        exec("INSERT INTO joint_projects VALUES(?,?,?,?,?,?,?,'OPEN',?)",id.toString(),owner.toString(),template.title(),template.result(),template.minimumCities(),encode(template.goods()),encode(profiles),System.currentTimeMillis());log("joint-plan",id.toString(),owner,actor,template.title());return readView(id);
    }));}
    public CompletionStage<JointView> contribute(UUID receipt,UUID project,UUID town,String profile,String product,int amount,String actor){return submit(()->transaction(()->{
        text(actor,64);if(amount<1||amount>64)throw new IllegalArgumentException("Передать можно 1–64 партии");try(var s=db.prepareStatement("SELECT project,town,product,amount FROM joint_contributions WHERE receipt=?")){s.setString(1,receipt.toString());try(var r=s.executeQuery()){if(r.next()){if(!r.getString(1).equals(project.toString())||!r.getString(2).equals(town.toString())||!r.getString(3).equals(product)||r.getInt(4)!=amount)throw new IllegalArgumentException("Квитанция занята другой передачей");return readView(project);}}}
        var v=readView(project);if(!v.project().state().equals("OPEN"))throw new IllegalArgumentException("Совместный проект закрыт");if(!profile.equals(v.project().profiles().get(product)))throw new IllegalArgumentException("Для этой поставки нужно другое направление города");
        String member=v.members().get(town);if(member!=null&&!member.equals(profile))throw new IllegalArgumentException("В этом проекте город уже представляет другое направление");if(member==null&&v.members().size()>=20)throw new IllegalArgumentException("В проекте уже 20 городов");
        long missing=v.project().goods().getOrDefault(product,0L)-v.supplied().getOrDefault(product,0L);if(amount>missing)throw new IllegalArgumentException("Нужно меньше партий: "+missing);
        try(var s=db.prepareStatement("UPDATE stock SET available=available-?,reserved=reserved+? WHERE town=? AND product=? AND available>=?")){s.setInt(1,amount);s.setInt(2,amount);s.setString(3,town.toString());s.setString(4,product);s.setInt(5,amount);if(s.executeUpdate()!=1)throw new IllegalArgumentException("Недостаточно свободных производственных партий");}
        exec("INSERT OR IGNORE INTO joint_members VALUES(?,?,?)",project.toString(),town.toString(),profile);exec("INSERT INTO joint_contributions VALUES(?,?,?,?,?,?,?)",receipt.toString(),project.toString(),town.toString(),product,amount,actor,System.currentTimeMillis());log("joint-contribution",receipt.toString(),town,actor,"Проект "+project+"; "+product+" × "+amount);return readView(project);
    }));}
    public CompletionStage<JointView> finishProject(UUID id,UUID owner,boolean cancel,String actor,String reason){return submit(()->transaction(()->{
        text(actor,64);text(reason,300);if(reason.trim().length()<8)throw new IllegalArgumentException("Укажите основание не короче 8 символов");var v=readView(id);if(!v.project().owner().equals(owner))throw new IllegalArgumentException("Завершает или отменяет проект город-организатор");String goal=cancel?"CANCELLED":"COMPLETED";if(v.project().state().equals(goal))return v;if(!v.project().state().equals("OPEN"))throw new IllegalArgumentException("Закрытый проект нельзя изменить");if(!cancel&&!v.funded())throw new IllegalArgumentException("Нужны все партии и участие городов разных направлений");
        try(var s=db.prepareStatement("SELECT town,product,SUM(amount) FROM joint_contributions WHERE project=? GROUP BY town,product")){s.setString(1,id.toString());try(var r=s.executeQuery()){while(r.next()){long count=r.getLong(3);try(var update=db.prepareStatement("UPDATE stock SET reserved=reserved-?,available=available+? WHERE town=? AND product=? AND reserved>=?")){update.setLong(1,count);update.setLong(2,cancel?count:0);update.setString(3,r.getString(1));update.setString(4,r.getString(2));update.setLong(5,count);if(update.executeUpdate()!=1)throw new SQLException("Резерв совместного проекта не совпадает с каталогом");}}}}
        exec("UPDATE joint_projects SET state=? WHERE id=?",goal,id.toString());log("joint-"+goal.toLowerCase(Locale.ROOT),id.toString(),owner,actor,reason);for(UUID member:v.members().keySet())if(!member.equals(owner))log("joint-"+goal.toLowerCase(Locale.ROOT),id+":"+member,member,actor,reason+"; проект "+id);return readView(id);
    }));}
    public CompletionStage<List<Map<String,Object>>> history(UUID town,int page){return submit(()->{page(page);var out=new ArrayList<Map<String,Object>>();try(var s=db.prepareStatement("SELECT id,kind,operation,actor,reason,at FROM history WHERE town=? ORDER BY at DESC,id LIMIT 20 OFFSET ?")){s.setString(1,town.toString());s.setLong(2,(page-1L)*20);try(var r=s.executeQuery()){while(r.next())out.add(Map.of("id",r.getString(1),"kind",r.getString(2),"operation",r.getString(3),"actor",r.getString(4),"reason",r.getString(5),"at",r.getLong(6)));}}return List.copyOf(out);});}
    public CompletionStage<List<ru.neverland.core.AuditRecord>> auditPending(){return submit(()->{var rows=new ArrayList<ru.neverland.core.AuditRecord>();try(var s=db.createStatement();var r=s.executeQuery("SELECT h.* FROM history h LEFT JOIN audit_ack a ON a.id=h.id WHERE a.id IS NULL ORDER BY h.at,h.id LIMIT 64")){while(r.next()){String town=r.getString("town");var city=new ru.neverland.core.AuditRecord.Party("TOWN",town,"Город "+town,town);var actor=new ru.neverland.core.AuditRecord.Party("PLAYER","",r.getString("actor"),town);rows.add(new ru.neverland.core.AuditRecord(r.getString("id"),r.getLong("at"),"NeverLandTownySpecialization","CITY_PROJECT",r.getString("kind"),r.getString("operation"),actor,city,city,"",0,"",r.getString("reason")));}}return List.copyOf(rows);});}
    public CompletionStage<Void> auditAcknowledged(List<String> ids){var frozen=List.copyOf(ids);if(frozen.size()>64)throw new IllegalArgumentException("Слишком большая пачка аудита");return submit(()->transaction(()->{for(String id:frozen)exec("INSERT OR IGNORE INTO audit_ack VALUES(?)",id);return null;}));}
    private void log(String kind,String operation,UUID town,String actor,String reason)throws SQLException{text(actor,64);String id=UUID.nameUUIDFromBytes((kind+":"+operation).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();exec("INSERT OR IGNORE INTO history VALUES(?,?,?,?,?,?,?)",id,kind,operation,town.toString(),actor,reason,System.currentTimeMillis());}
}
